const API_BASE = process.env.EXPO_PUBLIC_API_URL ?? 'http://127.0.0.1:8080';
const BACKOFF_MS = [1000, 2000, 5000] as const;

export type WsHandlers = {
  onMessageNew?: (payload: Message) => void;
  onMessageStatus?: (payload: MessageStatusPayload) => void;
  onTyping?: (payload: TypingPayload) => void;
  onChatUpdated?: (payload: Chat) => void;
  onOpen?: () => void;
  onClose?: () => void;
};

export type WsConnection = {
  sendTyping: (chatId: string) => void;
  close: () => void;
};

type WsEnvelope = {
  event: string;
  payload: unknown;
};

function toWsUrl(token: string): string {
  const base = API_BASE.replace(/^http/i, 'ws');
  const sep = base.includes('?') ? '&' : '?';
  return `${base}/ws${sep}token=${encodeURIComponent(token)}`;
}

export function connectWs(token: string, handlers: WsHandlers = {}): WsConnection {
  let socket: WebSocket | null = null;
  let closedByUser = false;
  let backoffIndex = 0;
  let reconnectTimer: ReturnType<typeof setTimeout> | null = null;

  const clearReconnect = () => {
    if (reconnectTimer !== null) {
      clearTimeout(reconnectTimer);
      reconnectTimer = null;
    }
  };

  const dispatch = (raw: string) => {
    let envelope: WsEnvelope;
    try {
      envelope = JSON.parse(raw) as WsEnvelope;
    } catch {
      return;
    }
    if (!envelope || typeof envelope.event !== 'string') return;

    switch (envelope.event) {
      case 'message.new':
        handlers.onMessageNew?.(envelope.payload as Message);
        break;
      case 'message.status':
        handlers.onMessageStatus?.(envelope.payload as MessageStatusPayload);
        break;
      case 'typing':
        handlers.onTyping?.(envelope.payload as TypingPayload);
        break;
      case 'chat.updated':
        handlers.onChatUpdated?.(envelope.payload as Chat);
        break;
      default:
        break;
    }
  };

  const scheduleReconnect = () => {
    if (closedByUser) return;
    clearReconnect();
    const delay = BACKOFF_MS[Math.min(backoffIndex, BACKOFF_MS.length - 1)];
    backoffIndex = Math.min(backoffIndex + 1, BACKOFF_MS.length - 1);
    reconnectTimer = setTimeout(() => {
      reconnectTimer = null;
      open();
    }, delay);
  };

  const open = () => {
    if (closedByUser) return;
    clearReconnect();

    const ws = new WebSocket(toWsUrl(token));
    socket = ws;

    ws.onopen = () => {
      backoffIndex = 0;
      handlers.onOpen?.();
    };

    ws.onmessage = (ev) => {
      if (typeof ev.data === 'string') {
        dispatch(ev.data);
      }
    };

    ws.onerror = () => {
      // onclose handles reconnect
    };

    ws.onclose = () => {
      if (socket === ws) {
        socket = null;
      }
      handlers.onClose?.();
      if (!closedByUser) {
        scheduleReconnect();
      }
    };
  };

  open();

  return {
    sendTyping(chatId: string) {
      if (!socket || socket.readyState !== WebSocket.OPEN) return;
      const envelope: WsEnvelope = {
        event: 'typing',
        payload: { chatId },
      };
      socket.send(JSON.stringify(envelope));
    },
    close() {
      closedByUser = true;
      clearReconnect();
      if (socket) {
        const ws = socket;
        socket = null;
        ws.close();
      }
    },
  };
}
